SCRIPT_FOLDERS = ["prologue", "chapter1", "chapter2", "chapter3", "chapter4", "chapter5", "chapter6", "chapter7", "chapter8", "chapter9", "chapter10",
                  "combat", "combat/enemies", "ui", "effects", "regions", "exploration", "overworld", "cutscene", "camera", "core", "dialogue", "resources", "debug"]

ASSET_FOLDERS = ["generated", "generated_v2", "generated_v3", "art_sources", "production_art", "sprites", "tilesets", "ui", "vfx", "audio", "backgrounds", "effects", "fonts"]

DOC_FOLDERS = ["archive", "art_pipeline", "gameplay_audit", "visual_review"]


def hygiene():
    out = [{"chore": c, "how": h, "done": d} for c, h, d in HYGIENE_HAND]
    for f in SCRIPT_FOLDERS:
        p = f"{G}/scripts/{f}"
        out.append({"chore": f"Orphan .uid sweep in scripts/{f}",
                    "how": f"for u in {p}/*.uid; do [ -f \"${{u%.uid}}\" ] || echo $u; done",
                    "done": f"scripts/{f} has no .uid without a matching script"})
        out.append({"chore": f"Unreferenced-script check in scripts/{f}",
                    "how": f"for s in {p}/*.gd; do n=$(basename $s); grep -rlq \"$n\" {G}/scenes {G}/project.godot {G}/scripts --exclude=$n || echo UNUSED $s; done",
                    "done": f"Every script in scripts/{f} is referenced, or listed for archive with approval"})
        out.append({"chore": f"TODO/FIXME and debug-print count in scripts/{f}",
                    "how": f"grep -cE 'TODO|FIXME' {p}/*.gd | grep -v ':0'; grep -c 'print(' {p}/*.gd | grep -v ':0'",
                    "done": f"Counts for scripts/{f} recorded in the debt register; any new TODO since last sweep has an issue"})
    for a in ASSET_FOLDERS:
        p = f"{G}/assets/{a}"
        out.append({"chore": f"Size and LFS check for assets/{a}",
                    "how": f"du -sh {p}; find {p} -type f -size +500k -not -name '*.import' | head",
                    "done": f"assets/{a} size recorded; files over 500 KB have an LFS decision"})
        out.append({"chore": f"Unreferenced-file scan for assets/{a}",
                    "how": f"for f in $(find {p} -type f -not -name '*.import'); do grep -rlq \"$(basename $f)\" {G}/scenes {G}/scripts {G}/assets --include='*.tscn' --include='*.tres' --include='*.gd' || echo $f; done | head -50",
                    "done": f"Unreferenced files in assets/{a} listed; archive decision recorded (art_sources stays review-only)"})
        out.append({"chore": f".import pairing check for assets/{a}",
                    "how": f"find {p} -name '*.import' | while read i; do [ -f \"${{i%.import}}\" ] || echo STALE $i; done; find {p} -name '*.png' | while read f; do [ -f \"$f.import\" ] || echo NOIMPORT $f; done",
                    "done": f"assets/{a} has no stale .import files and no unimported PNGs (unless .gdignore'd)"})
    for d in DOC_FOLDERS:
        p = f"{G}/docs/{d}"
        out.append({"chore": f"Stale-probe review of docs/{d}",
                    "how": f"ls -lt {p} | tail -15; mark files older than 90 days as keep/archive; check nothing in scripts reads them",
                    "done": f"docs/{d} has a dated index or every old file is archived"})
        out.append({"chore": f"Size check of docs/{d}",
                    "how": f"du -sh {p}; find {p} -type f -size +1M | head",
                    "done": f"docs/{d} size recorded; large images have an LFS or prune decision"})
    return out


