def code_quality():
    out = [{"item": i, "check": c, "fix": f} for i, c, f in CQ_HAND]
    for n, p in AUTOLOADS:
        for it, c, f in CQ_PER_AUTOLOAD:
            out.append({"item": it.format(n=n, p=p), "check": c.format(G=G, p=p), "fix": f.format(p=p)})
    return out
